 hairshape='' if bald else (f'<path d="M25 48 Q32 12 60 14 Q90 14 96 49 Q80 30 60 31 Q40 30 25 48" fill="{hair}"/>' + (f'<path d="M27 43 Q18 75 28 104 L39 82 L39 42Z M93 43 Q103 75 92 104 L81 82 L81 42Z" fill="{hair}"/>' if long else ''))
