CSS='''*{box-sizing:border-box}body{margin:0;background:#08080b;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}.shell{max-width:1180px;margin:auto;padding:0 18px}.nav{position:sticky;top:0;z-index:20;background:#08080bee;border-bottom:1px solid #292932}.navin{height:70px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:900;font-size:22px}.tm{font-size:.48em;vertical-align:super;margin-left:2px}.grad{background:linear-gradient(90deg,#63d7ff,#d45fff,#ff688e);-webkit-background-clip:text;color:transparent}.links{display:flex;gap:18px;color:#bbb}.hero{min-height:500px;display:grid;grid-template-columns:1.1fr .9fr;align-items:center;gap:34px}.hero h1{font-size:clamp(50px,8vw,88px);line-height:.94;margin:12px 0}.lead,.sub{color:#bbb;line-height:1.55}.lead{font-size:20px}.art{min-height:340px;border:1px solid #333;border-radius:32px;display:grid;place-items:center;text-align:center;background:radial-gradient(circle at 65% 30%,#5d1b6b,transparent 34%),radial-gradient(circle at 30% 65%,#0a405f,transparent 35%),#101016}.heart{font-size:90px}.section{padding:58px 0}.section h2{font-size:40px}.grid{display:grid;grid-template-columns:repeat(8,1fr);gap:12px}.comp{background:#131319;border:1px solid #303039;border-radius:18px;padding:10px;text-align:center}.comp:hover{border-color:#a85fff;transform:translateY(-2px)}.avatar{width:82px;height:82px;margin:0 auto 9px;border-radius:16px;overflow:hidden;background:#222}.avatar img{width:100%;height:100%;object-fit:cover}.comp small{display:block;color:#72d8a0;font-size:9px;margin-top:4px}.plans{display:grid;grid-template-columns:1fr 1fr;gap:18px}.plan,.card{background:#131319;border:1px solid #35353e;border-radius:25px;padding:26px}.plan.hot{border-color:#d36580}.price{font-size:40px;font-weight:900}.btn{display:inline-block;background:#d36580;border:0;color:#fff;border-radius:16px;padding:14px 19px;font-weight:800;cursor:pointer}.btn.alt{background:#19191f;border:1px solid #444}.fine{text-align:center;color:#888;font-size:12px;padding:35px 0 55px}.back{display:inline-block;margin:24px 0;color:#aaa}.profile{display:grid;grid-template-columns:190px 1fr;gap:24px;align-items:center}.bigavatar{width:165px;height:165px;border-radius:24px;overflow:hidden}.bigavatar img{width:100%;height:100%;object-fit:cover}.bubble{background:#29292f;border-radius:22px;padding:17px;margin:12px 0;font-size:18px}.you{background:#202026}.row{display:flex;gap:10px}.row input{flex:1;min-width:0;background:#09090b;color:#fff;border:1px solid #555;border-radius:18px;padding:16px;font-size:17px}.status,.note{color:#aaa;font-size:13px;margin-top:10px}.chips{display:flex;flex-wrap:wrap;gap:9px}.chip{background:#202026;border:1px solid #45454d;border-radius:999px;padding:10px 13px;cursor:pointer}.chip.active{background:#d36580}.group{margin-top:18px}.banner{display:inline-block;background:#17121a;border:1px solid #57334a;border-radius:18px;padding:12px;color:#edc6d1}.account{max-width:620px;margin:45px auto}.field{display:grid;gap:7px;margin:15px 0}.field input{background:#09090b;border:1px solid #444;border-radius:14px;padding:14px;color:#fff}@media(max-width:850px){.hero{grid-template-columns:1fr}.grid{grid-template-columns:repeat(4,1fr)}.plans{grid-template-columns:1fr}.profile{grid-template-columns:1fr}.links{display:none}}@media(max-width:480px){.grid{grid-template-columns:repeat(2,1fr)}.avatar{width:100px;height:100px}}'''
