def home():
 b=f'''<main class="shell"><section class="hero"><div><div class="grad">AI COMPANIONS</div><h1>Someone to talk to.<br><span class="grad">Someone who remembers.</span></h1><p class="lead">Meet 32 distinct AI companions with personality, conversation, multiple languages and premium customization.</p><a class="btn" href="#companions">Meet the Companions</a> <a class="btn alt" href="/simone">Talk to Simone</a></div><div class="art"><div><div class="heart">♡</div><h2>What <span class="grad">Bout Us<span class="tm">™</span></span></h2><p>AI COMPANIONS</p></div></div></section><section id="companions" class="section"><h2>32 AI Companions</h2><p class="sub">16 men. 16 women. Tap any picture to open a live conversation.</p><h3>16 MEN</h3><div class="grid">{cards(MEN)}</div><h3 style="margin-top:28px">16 WOMEN</h3><div class="grid">{cards(WOMEN)}</div></section><section id="plans" class="section"><h2>Choose Your Experience</h2><div class="plans"><div class="plan"><h3>WHAT BOUT US™+</h3><div class="price">$9.99 <small>/ month</small></div><ul><li>Text conversations</li><li>Multiple companions</li><li>Conversation memory</li><li>Multiple languages</li></ul><a class="btn alt" href="/checkout?plan=plus">Choose Plus</a></div><div class="plan hot"><h3>WHAT BOUT US™ UNLIMITED</h3><div class="price">$14.99 <small>/ month</small></div><ul><li>Everything in Plus</li><li>All 32 companions</li><li>Voice-ready conversations</li><li>Premium style customization</li><li>Expanded accessories</li></ul><a class="btn" href="/checkout?plan=unlimited">Choose Unlimited</a></div></div></section>{footer()}</main>'''; return page('What Bout Us™ — AI Companions',b)
def companion_page(name):
 intro="Hey U, I'm Simone. Tell me what you're thinking." if name=='Simone' else f"Hey, I'm {name}. What's on your mind?"; premium=''
 if name=='Simone': premium='''<div class="card" style="margin-top:18px"><h2>Premium Style</h2><p class="sub">Expanded accessories and style customization.</p><div class="group"><h3>Outfit</h3><div class="chips" data-group="outfit"><span class="chip">Casual</span><span class="chip">Business</span><span class="chip">Evening</span><span class="chip">Athletic</span><span class="chip">Streetwear</span><span class="chip">Dressy</span></div></div><div class="group"><h3>Expanded Accessories</h3><div class="chips multi" data-group="accessories"><span class="chip">Sunglasses</span><span class="chip">Watch</span><span class="chip">Bracelet</span><span class="chip">Necklace</span><span class="chip">Chain</span><span class="chip">Hat</span><span class="chip">Earrings</span><span class="chip">Scarf</span><span class="chip">Bag</span><span class="chip">Ring</span></div></div><div class="group"><h3>Footwear</h3><div class="chips" data-group="footwear"><span class="chip">Sneakers</span><span class="chip">Dress Shoes</span><span class="chip">Sandals</span><span class="chip">Work Boots</span><span class="chip">Timberland-Style Boots</span><span class="chip">Cowboy Boots</span><span class="chip">Hiking Boots</span></div></div><button class="btn" onclick="saveStyle()" style="margin-top:18px">Save Style</button><span id="saved" class="status"></span></div>'''
 b=f'''<main class="shell"><a class="back" href="/">← Back to all companions</a><div class="card"><div class="profile"><div class="bigavatar"><img src="{portrait(name)}" alt="{esc(name)}"></div><div><div class="grad">LIVE COMPANION</div><h1>{esc(name)}</h1><p class="lead" style="font-size:17px">{esc(TRAITS.get(name,'warm, supportive and engaging').capitalize())}.</p>{'<span class="banner">Simone voice is enabled.</span>' if name=='Simone' else ''}</div></div><div class="bubble">{esc(intro)}</div><div id="history"></div><div class="row"><input id="message" placeholder="Talk to {esc(name)}..."><button class="btn" onclick="sendMessage()">Send</button></div><div id="status" class="status">Ready</div></div>{premium}{footer()}</main><script>const NAME={json.dumps(name)},H=document.getElementById('history');function x(t){{let d=document.createElement('div');d.textContent=t;return d.innerHTML}}async function sendMessage(){{let i=document.getElementById('message'),m=i.value.trim(),s=document.getElementById('status');if(!m)return;i.value='';H.innerHTML+='<div class="bubble you">You: '+x(m)+'</div>';s.textContent=NAME+' is thinking...';try{{let r=await fetch('/api/chat',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{message:m,companion:NAME}})}}),d=await r.json();H.innerHTML+='<div class="bubble">'+NAME+': '+x(d.reply)+'</div>';s.textContent='Ready';if(NAME==='Simone'){{let q=await fetch('/api/speech',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{text:d.reply}})}});if(q.ok)new Audio(URL.createObjectURL(await q.blob())).play()}}}}catch(e){{s.textContent='Connection error'}}}}document.getElementById('message').addEventListener('keydown',e=>{{if(e.key==='Enter')sendMessage()}});document.querySelectorAll('.chips').forEach(g=>g.onclick=e=>{{if(!e.target.classList.contains('chip'))return;if(g.classList.contains('multi'))e.target.classList.toggle('active');else{{g.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));e.target.classList.add('active')}}}});function saveStyle(){{let o={{}};document.querySelectorAll('.chips').forEach(g=>o[g.dataset.group]=[...g.querySelectorAll('.active')].map(c=>c.textContent));localStorage.setItem('simoneStyle',JSON.stringify(o));document.getElementById('saved').textContent=' Saved'}}</script>'''; return page(name+' — What Bout Us™',b)
def account_page(): return page('Account — What Bout Us™','<main class="shell"><div class="account card"><h1>Your Account</h1><p class="sub">Account authentication is being connected.</p><div class="field"><label>Display name</label><input></div><div class="field"><label>Email</label><input type="email"></div></div>'+footer()+'</main>')
def chat_reply(c,m):
 c=c if c in ALL else 'Simone'
 if not OPENAI_API_KEY:return "I'm here with you. Tell me a little more about that."
 sys=f'You are {c}, an adult AI companion in What Bout Us™. Personality: {TRAITS.get(c)}. Be warm, concise and natural. Never claim to be human. Users must be 21+. Never sexualize minors or discuss sexual activity involving minors, babies, animals or insects.'; data=json.dumps({'model':'gpt-4o-mini','messages':[{'role':'system','content':sys},{'role':'user','content':m}],'max_tokens':220}).encode(); req=urllib.request.Request('https://api.openai.com/v1/chat/completions',data=data,headers={'Authorization':'Bearer '+OPENAI_API_KEY,'Content-Type':'application/json'})
 try:
  with urllib.request.urlopen(req,timeout=30) as r:return json.loads(r.read().decode())['choices'][0]['message']['content'].strip()
 except:return "I'm here with you. Tell me a little more about that."
def audio(t):
 if not(ELEVENLABS_API_KEY and ELEVENLABS_VOICE_ID):return None
 data=json.dumps({'text':t[:1200],'model_id':'eleven_multilingual_v2'}).encode(); req=urllib.request.Request('https://api.elevenlabs.io/v1/text-to-speech/'+quote(ELEVENLABS_VOICE_ID),data=data,headers={'xi-api-key':ELEVENLABS_API_KEY,'Content-Type':'application/json','Accept':'audio/mpeg'})
 try:
  with urllib.request.urlopen(req,timeout=35) as r:return r.read()
 except:return None
class H(BaseHTTPRequestHandler):
 def sh(self,s,status=200):
  b=s.encode();self.send_response(status);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Cache-Control','no-store');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def sj(self,d,status=200):
  b=json.dumps(d).encode();self.send_response(status);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def do_GET(self):
  u=urlparse(self.path);p=u.path
  if p=='/health':return self.sj({'ok':True,'companions':32,'portraits':True,'copyright':2026,'trademark':True})
  if p=='/':return self.sh(home())
  if p=='/simone':self.send_response(302);self.send_header('Location','/companion/simone');self.end_headers();return
  if p.startswith('/companion/'):
   slug=unquote(p.split('/companion/',1)[1]).lower();n=next((x for x in ALL if x.lower()==slug),None);return self.sh(companion_page(n)) if n else self.sh('Not found',404)
  if p=='/account':return self.sh(account_page())
  if p=='/checkout':
   plan=parse_qs(u.query).get('plan',['plus'])[0];target=SQUARE_UNLIMITED_URL if plan=='unlimited' else SQUARE_PLUS_URL
   if target:self.send_response(302);self.send_header('Location',target);self.end_headers();return
   return self.sh(page('Checkout — What Bout Us™','<main class="shell"><div class="account card"><h1>Secure Checkout</h1><p class="banner">Square checkout is being connected.</p></div>'+footer()+'</main>'))
  return self.sh('Not found',404)
 def do_POST(self):
  n=int(self.headers.get('Content-Length','0') or 0)
  try:d=json.loads(self.rfile.read(n).decode() or '{}')
  except:d={}
  if self.path=='/api/chat':return self.sj({'reply':chat_reply(str(d.get('companion','Simone')),str(d.get('message',''))[:3000])})
  if self.path=='/api/speech':
   a=audio(str(d.get('text','')))
   if not a:return self.sj({'error':'Voice unavailable'},503)
   self.send_response(200);self.send_header('Content-Type','audio/mpeg');self.send_header('Content-Length',str(len(a)));self.end_headers();self.wfile.write(a);return
  return self.sj({'error':'Not found'},404)
 def log_message(self,*a):pass
if __name__=='__main__':ThreadingHTTPServer(('0.0.0.0',PORT),H).serve_forever()
